INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1377633, 176724, 25309, '<td valign="top">what are the marks on the floor? It kind of get more my attention than the piramide.</td>', 'what are the marks on the floor? It kind of get more my attention than the piramide.', '2005-05-11 09:01:12.000000', NULL, 1),
