(1378374, 175572, 34659, '<td valign="top">Beautiful shot!  It''s a little blurry (probably due to the distance), but the colors and composition are very nice.  It''s a shame you couldn''t have been higher above the glider too, resulting in a larger view of the kite, but overall a very nice job.  (6)</td>', 'Beautiful shot!  It''s a little blurry (probably due to the distance), but the colors and composition are very nice.  It''s a shame you couldn''t have been higher above the glider too, resulting in a larger view of the kite, but overall a very nice job.  (6)', '2005-05-11 12:40:51.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1378375, 176567, 3419, '<td valign="top">I like this concept, and I like the lighting. However, the focus seems a bit soft. There''s a bit of distracting subject matter in the bottom right corner that you should crop out.</td>', 'I like this concept, and I like the lighting. However, the focus seems a bit soft. There''s a bit of distracting subject matter in the bottom right corner that you should crop out.', '2005-05-11 12:41:03.000000', NULL, 1),
(1378376, 176531, 36299, '<td valign="top">Took a second to figure this out.  Over sharpening by camera or processing takes from this photo, the darkness is okay, but feel that a shallower DOF would give a better triangle.  7</td>', 'Took a second to figure this out.  Over sharpening by camera or processing takes from this photo, the darkness is okay, but feel that a shallower DOF would give a better triangle.  7', '2005-05-11 12:41:08.000000', NULL, 1),
(1378377, 175878, 327, '<td valign="top">Your sun light is a bit too bright and I think the framing/composition is a bit boring. This meets the challenge but it''s not interesting and doesn''t grab the viewer.</td>', 'Your sun light is a bit too bright and I think the framing/composition is a bit boring. This meets the challenge but it''s not interesting and doesn''t grab the viewer.', '2005-05-11 12:42:03.000000', NULL, 1),
(1378378, 176180, 327, '<td valign="top">Great looking building and good sky is a bonus here.</td>', 'Great looking building and good sky is a bonus here.', '2005-05-11 12:42:21.000000', NULL, 1),
(1378380, 174214, 36299, '<td valign="top">Nice triangle, a bit more in focus would help here, for me, and slightly different cropping would leave a more obvious double triangle one from the garden and an implied mirrored one with the posts. 8</td>', 'Nice triangle, a bit more in focus would help here, for me, and slightly different cropping would leave a more obvious double triangle one from the garden and an implied mirrored one with the posts. 8', '2005-05-11 12:42:51.000000', NULL, 1),
(1378381, 176452, 34659, '<td valign="top">Absolutely gorgeous shot!  I can''t believe how close up &amp; detailed this is!  I''ve given out very few 10s, but this is certainly worthy!  Outstanding job!  (10)</td>', 'Absolutely gorgeous shot!  I can''t believe how close up & detailed this is!  I''ve given out very few 10s, but this is certainly worthy!  Outstanding job!  (10)', '2005-05-11 12:42:54.000000', NULL, 1),
(1378382, 176451, 3419, '<td valign="top">Is this a windchime/suncatcher? Cool piece! Exposure, focus, and composition are all good.</td>', 'Is this a windchime/suncatcher? Cool piece! Exposure, focus, and composition are all good.', '2005-05-11 12:43:08.000000', NULL, 1),
(1378384, 175367, 3419, '<td valign="top">out of focus and spelling error to boot.</td>', 'out of focus and spelling error to boot.', '2005-05-11 12:43:33.000000', NULL, 1),
