(1378387, 175188, 36299, '<td valign="top">nice implied triangle, slightly different angle to get more of it in the shot, or cropping would make it nicer for me. 8</td>', 'nice implied triangle, slightly different angle to get more of it in the shot, or cropping would make it nicer for me. 8', '2005-05-11 12:43:50.000000', NULL, 1),
(1378390, 175170, 3419, '<td valign="top">Pretty scene, but out of focus. Recommend using a tripod for night time shots.</td>', 'Pretty scene, but out of focus. Recommend using a tripod for night time shots.', '2005-05-11 12:44:29.000000', NULL, 1),
(1378391, 176452, 36299, '<td valign="top">WOW!  I feel like lunch.  10</td>', 'WOW!  I feel like lunch.  10', '2005-05-11 12:44:30.000000', NULL, 1),
