(1379469, 175953, 33352, '<td valign="top">Impressive, and well composed....9</td>', 'Impressive, and well composed....9', '2005-05-11 17:59:19.000000', NULL, 1),
(1379472, 176498, 24991, '<td valign="top">Uhhh, I understand the idea you were going for, but I really disagree.  Usually, a triangel is formed by the outer edges being defined, rather than lines running out to the corners.  It is a good idea, but I don''t feel it fits within the definition of the challenge.  Additionally, I think that the shot could have been lit a lot better, and you could have chosen a tulip with a lot better colors.  Nice shot anyway I suppose.</td>', 'Uhhh, I understand the idea you were going for, but I really disagree.  Usually, a triangel is formed by the outer edges being defined, rather than lines running out to the corners.  It is a good idea, but I don''t feel it fits within the definition of the challenge.  Additionally, I think that the shot could have been lit a lot better, and you could have chosen a tulip with a lot better colors.  Nice shot anyway I suppose.', '2005-05-11 17:59:59.000000', NULL, 1),
(1379474, 175465, 24991, '<td valign="top">Cool, never thought of looking there, but it is.</td>', 'Cool, never thought of looking there, but it is.', '2005-05-11 18:00:51.000000', NULL, 1);
