(1382266, 174729, 36914, '<td valign="top">Could be lightened a little more  good catch on the bird flying off.</td>', 'Could be lightened a little more  good catch on the bird flying off.', '2005-05-12 20:35:20.000000', NULL, 1),
(1382271, 175599, 27246, '<td valign="top">I find the horizontal line (horizon) distracting. Colors are nice, but could be brighter with better lighting and pure white background</td>', 'I find the horizontal line (horizon) distracting. Colors are nice, but could be brighter with better lighting and pure white background', '2005-05-12 20:38:04.000000', NULL, 1),
(1382275, 176244, 36914, '<td valign="top">Very nice and very sharp you should be in the top 3 or even number one.</td>', 'Very nice and very sharp you should be in the top 3 or even number one.', '2005-05-12 20:38:56.000000', NULL, 1),
