(1385218, 175896, 37380, '<td valign="top">I''ve seen the gherkin in a number of photos now, but this is my favourite with a nice range of colours.</td>', 'I''ve seen the gherkin in a number of photos now, but this is my favourite with a nice range of colours.', '2005-05-14 08:52:02.000000', NULL, 1),
(1385219, 176452, 7304, '<td valign="top">Awesome photo and capture of the triangle. Nice and clean, great color and light. 10</td>', 'Awesome photo and capture of the triangle. Nice and clean, great color and light. 10', '2005-05-14 08:52:45.000000', NULL, 1),
