(1386743, 176090, 30881, '<td valign="top">probably the best shot I''ve seen in a very long long time using reflective surfaces.<br/>Excellent work!</td>', 'probably the best shot I''ve seen in a very long long time using reflective surfaces.Excellent work!', '2005-05-15 12:06:04.000000', NULL, 1),
(1386746, 175448, 19841, '<td valign="top">How beautifully mysterious!</td>', 'How beautifully mysterious!', '2005-05-15 12:12:01.000000', NULL, 1),
